void detail_layout(void){
 Detail*d=app.editor;if(!d||!d->hwnd)return;ui_update_begin(app.window);RECT r;GetClientRect(app.window,&r);
 SetWindowPos(d->hwnd,HWND_TOP,r.right-U(GX_DRAWER),0,U(GX_DRAWER),r.bottom-U(GX_FOOT),SWP_NOACTIVATE|SWP_NOREDRAW);
 int head=*str(d->data,"parentId")||app.depth?78:46;ui_show(d->fields[F_BREAD],head>46?SW_SHOW:SW_HIDE);
 RECT pane;GetClientRect(d->hwnd,&pane);MoveWindow(d->scroll,1,U(head),pane.right-1,max(0,pane.bottom-U(head)),FALSE);ui_update_end();
}
void detail_destroy(void){
 Detail*d=app.editor;if(!d||d->closed)return;int update=app.ready;
 /* Mark closed before synchronous destruction callbacks. Keep the owner-data
    cache alive until DestroyWindow returns; no re-entrant save/layout sees the pane. */
 ui_drag_cancel();d->closed=1;app.editor=0;
 if(update)ui_update_begin(app.window);
 HWND pane=d->hwnd;d->hwnd=0;
 if(d->childList&&IsWindow(d->childList))SendMessageW(d->childList,WM_SETREDRAW,FALSE,0);
 if(pane&&IsWindow(pane))DestroyWindow(pane);
 d->childList=0;d->children.hwnd=0;ui_view_clear(&d->children);d->children.count=0;
 free(d->key);cJSON_Delete(d->base);cJSON_Delete(d->data);cJSON_Delete(d->context);free(d);app.drawerWidth=0;
 if(update){ui_refresh(0);ui_update_end();}
}


